window.ScripturaLexicons.BDAG_PART_0337 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-01\" data-source=\"BDAG\" data-search=\"σῦκον, ου, τό substantivo neutro figo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σῦκον, ου, τό</td><td>substantivo neutro</td><td>figo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-02\" data-source=\"BDAG\" data-search=\"συκοφαντέω verbo caluniar; coagir; extorquir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συκοφαντέω</td><td>verbo</td><td>caluniar; coagir; extorquir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-03\" data-source=\"BDAG\" data-search=\"συλαγωγέω verbo levar como despojo; fazer cativo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλαγωγέω</td><td>verbo</td><td>levar como despojo; fazer cativo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-04\" data-source=\"BDAG\" data-search=\"συλάω verbo roubar; saquear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλάω</td><td>verbo</td><td>roubar; saquear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-05\" data-source=\"BDAG\" data-search=\"συλλαβή, ῆς, ἡ substantivo feminino sílaba BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλλαβή, ῆς, ἡ</td><td>substantivo feminino</td><td>sílaba</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-06\" data-source=\"BDAG\" data-search=\"συλλαλέω verbo conversar; discutir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλλαλέω</td><td>verbo</td><td>conversar; discutir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-07\" data-source=\"BDAG\" data-search=\"συλλαμβάνω verbo prender; capturar; conceber; auxiliar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλλαμβάνω</td><td>verbo</td><td>prender; capturar; conceber; auxiliar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-08\" data-source=\"BDAG\" data-search=\"συλλέγω verbo reunir; recolher; colher BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλλέγω</td><td>verbo</td><td>reunir; recolher; colher</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-09\" data-source=\"BDAG\" data-search=\"σύλλημμα, ατος, τό substantivo neutro feto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύλλημμα, ατος, τό</td><td>substantivo neutro</td><td>feto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-10\" data-source=\"BDAG\" data-search=\"σύλληψις, εως, ἡ substantivo feminino concepção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύλληψις, εως, ἡ</td><td>substantivo feminino</td><td>concepção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-11\" data-source=\"BDAG\" data-search=\"συλλογίζομαι verbo raciocinar; discutir; ponderar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλλογίζομαι</td><td>verbo</td><td>raciocinar; discutir; ponderar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-12\" data-source=\"BDAG\" data-search=\"συλλυπέω verbo entristecer-se; sentir compaixão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συλλυπέω</td><td>verbo</td><td>entristecer-se; sentir compaixão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-13\" data-source=\"BDAG\" data-search=\"συμβαίνω verbo ir juntamente; acontecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμβαίνω</td><td>verbo</td><td>ir juntamente; acontecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-14\" data-source=\"BDAG\" data-search=\"συμβάλλω verbo conferenciar; ponderar; comparar; encontrar; combater; ajudar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμβάλλω</td><td>verbo</td><td>conferenciar; ponderar; comparar; encontrar; combater; ajudar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-15\" data-source=\"BDAG\" data-search=\"συμβασιλεύω verbo reinar conjuntamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμβασιλεύω</td><td>verbo</td><td>reinar conjuntamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-16\" data-source=\"BDAG\" data-search=\"συμβιβάζω verbo unir; inferir; demonstrar; instruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμβιβάζω</td><td>verbo</td><td>unir; inferir; demonstrar; instruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-17\" data-source=\"BDAG\" data-search=\"σύμβιος, ον adjetivo substantivado companheiro; marido; esposa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σύμβιος, ον</td><td>adjetivo substantivado</td><td>companheiro; marido; esposa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-18\" data-source=\"BDAG\" data-search=\"συμβουλεύω verbo aconselhar; deliberar; meditar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμβουλεύω</td><td>verbo</td><td>aconselhar; deliberar; meditar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-19\" data-source=\"BDAG\" data-search=\"συμβουλή, ῆς, ἡ substantivo feminino conselho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμβουλή, ῆς, ἡ</td><td>substantivo feminino</td><td>conselho</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0337-20\" data-source=\"BDAG\" data-search=\"συμβουλία, ας, ἡ substantivo feminino conselho BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">συμβουλία, ας, ἡ</td><td>substantivo feminino</td><td>conselho</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0337-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σῦκον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σῦκον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom. et al.; inscrições, papiros, LXX; JosAs 4:4; ParJer; ApcMos 20; Jos., Bell. 3, 519, Vi. 14) fruto da figueira, figo (v. <span class=\"greek\">συκῆ</span>), especialmente figo maduro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:12</a>.—B. 378. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συκοφαντέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συκοφαντέω</span> futuro, 3.ª pessoa do singular <span class=\"greek\">συκοφαντῆσει</span> Lev 19:11; 1.º aoristo <span class=\"greek\">ἐσυκοφάντησα</span>; futuro passivo, 3.ª pessoa do singular <span class=\"greek\">συκοφαντηθήσεται</span> (Just., D. 92, 5) (Aristoph., X., Pla. et al.; papiros, LXX; TestJos 8:4; Philo; Jos., Bell. 1, 11, Ant. 10, 114, Vi. 52; SibOr 2, 73). Primariamente ‘acusar falsamente, caluniar’ (para conjecturas sobre a derivação do termo v. L-S-M-J s.v. <span class=\"greek\">συκοφάντης</span> e a bibliografia abaixo)</p>\n<p class=\"entry-text\">① exercer pressão sobre alguém para proveito pessoal, importunar, coagir, extorquir, chantagear <span class=\"greek\">τινά</span> alguém (Pr 14:31; 22:16 <span class=\"greek\">πένητα</span>; 28:3 <span class=\"greek\">πτωχούς</span>) com <span class=\"greek\">διασείω</span> (BGU 1756, 11 [I a.C.]; v. <span class=\"greek\">διασείω</span> e cf. também Antiphon, Or. 6, 43; UPZ 113, 9f [156 a.C.]; PTebt 43, 26 <span class=\"greek\">συκοφαντηθῶμεν</span> e 36 <span class=\"greek\">συκοφαντίας</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διασισμοῦ</span> <span class=\"greek\">χάριν</span>=para fins de calúnia e extorsão mediante intimidação) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:14</a>.</p>\n<p class=\"entry-text\">② obter algo mediante intimidação, extorquir (Lysias 26, 24 <span class=\"greek\">τὶ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>) <span class=\"greek\">εἴ</span> <span class=\"greek\">τινός</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἐσυκοφάντησα</span> se extorqui algo de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:8</a>.—EbNestle, Sykophantia im bibl. Griech.: ZNW 4, 1903, 271f; JLofberg, The Sycophant-Parasite: ClPh 15, 1920, 61–72. Sobre a derivação do termo v. especialmente KLatte, Pauly-W. IV A (1932) 1028–31. V. também Arnott, Alexis p. 551f.—DELG s.v. <span class=\"greek\">σῦκον</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλαγωγέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλαγωγέω</span> apoderar-se de alguém levando-o como despojo, fazer cativo, roubar <span class=\"greek\">τινά</span> alguém (Tat. 22, 2 [figurado]; Heliod. 10, 35 p. 307, 32 Bekker <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐμὴν</span> <span class=\"greek\">θυγατέρα</span> <span class=\"greek\">συλαγωγήσας</span>; Aristaen. 2, 22 Hercher), em linguagem figurada de arrebatar alguém da verdade para a escravidão do erro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:8</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλάω</span> 1.º aoristo <span class=\"greek\">ἐσύλησα</span>; perfeito, 2.ª pessoa do plural <span class=\"greek\">σεσυλήκατε</span> (Tat. 10, 2). Passivo: subjuntivo do aoristo, 3.ª pessoa do plural <span class=\"greek\">συληθῶσι</span> EpJer 17 (Hom. et al.; inscrições, papiros; EpJer 17; Jos., C. Ap. 2, 263) roubar, saquear <span class=\"greek\">τινά</span> alguém, como expressão figurada dramática do procedimento de Paulo ao aceitar auxílio financeiro de certas fontes <span class=\"greek\">ἄλλας</span> <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">ἐσύλησα</span> saqueei (ou pilhei/assaltei) outras igrejas e assim obtive o dinheiro que me permitiu servir-vos gratuitamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:8</a>. Talvez se aplique aqui o sentido técnico exercer o direito de apreensão (IG IX/1, 333, 3 [V a.C.] et al.; v. L-S-J-M 3d e s.v. <span class=\"greek\">σύλη</span> I; Spicq s.v.).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλλαβή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλλαβή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Aeschyl.) sílaba (Pla., Demosth. et al.; Philo, Poster. Cai. 94) Hv 2, 1, 4 (Porphyr., Vi. Plot. 8 <span class=\"greek\">ἔγραψε</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κάλλος</span> <span class=\"greek\">ἀποτυπούμενος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">γράμματα</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">εὐσήμως</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">συλλαβὰς</span> <span class=\"greek\">διαιρῶν</span>=escrevia sem interesse pela beleza das letras nem indicação clara da divisão das sílabas).—DELG s.v. <span class=\"greek\">λαμβάνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλλαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλλαλέω</span> imperfeito <span class=\"greek\">συνελάλουν</span>; 1.º aoristo <span class=\"greek\">συνελάλησα</span> (Polyb.; OGI 229, 23; papiros, LXX) trocar pensamentos com, falar/discutir/conversar com <span class=\"greek\">τινί</span> alguém (Polyb. 4, 22, 8; PHib 66, 4 [III a.C.]; PRainer 18, 23; Ex 34:35; Pr 6:22; Is 7:6; TestJob 30:3 <span class=\"greek\">ἀλλήλοις</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:30</a>; 22:4. Também <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:12</a> D; 25:12. <span class=\"greek\">συνελάλουν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">λέγοντες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:36</a>.—M-M s.v. <span class=\"greek\">συνλαλέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλλαμβάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλλαμβάνω</span> futuro <span class=\"greek\">συλλήμψομαι</span> e <span class=\"greek\">συλλήψεις</span> GJs 4:1 (sobre a grafia v. <span class=\"greek\">λαμβάνω</span>); 2.º aoristo <span class=\"greek\">συνέλαβον</span>; perfeito <span class=\"greek\">συνείληφα</span>; 2.º aoristo médio <span class=\"greek\">συνελαβόμην</span>. Passivo: 1.º futuro <span class=\"greek\">συλληφθήσομαι</span> LXX; 1.º aoristo <span class=\"greek\">συνελήμφθην</span> (Aeschyl., Hdt.+).</p>\n<p class=\"entry-text\">① prender, deter</p>\n<p class=\"entry-text\">ⓐ agarrar, apoderar-se de, apreender <span class=\"greek\">τινά</span> prender alguém (Soph., Thu. et al.; SIG 700, 30; PHib 54, 20; POxy 283, 12 e outras ocorrências; LXX; Jos., Bell. 2, 292, Ant. 15, 124; Just., D. 111, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:54</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:16</a>; 12:3; 1 Cl 12:2a. Passivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:27</a>; 1 Cl 12:2b; MPol 5:2; 7:2; 9:1; 21.</p>\n<p class=\"entry-text\">ⓑ médio, agarrar, prender <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:21</a>; MPol 6:1.</p>\n<p class=\"entry-text\">② capturar (um animal), apanhar (Dio Chrys. 25 [42], 3; Aelian, HA 1, 2; Philo, Omn. Prob. Lib. 147) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:9</a> (v. <span class=\"greek\">ἄγρα</span>).</p>\n<p class=\"entry-text\">③ engravidar, conceber, de uma mulher (Aristot., HA 7, 1, 582a, 19, Gen. An. 1, 19, 727b, 8; Plut., Mor. 829b; Lucian, Sacrif. 5; LXX; cf. EpArist 165; sobre escritores médicos v. Hobart 91f) uso absoluto, engravidar (Gen 4:1; 30:7 e outras ocorrências; Tat. 33, 3; Ath. 22, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:24</a>; B 13:2; GJs 4:1; <span class=\"greek\">συλλήμψομαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">λόγου</span> (<span class=\"greek\">θεοῦ</span>) … <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῶντος</span> 11:2; ApcP 11:26 margem, conforme a restauração de Dieterich et al. Também <span class=\"greek\">συλλ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">γαστρί</span> (Hippocr., Aph. 5, 46 ed. Littré; IV 548, Mul. 1, 75 vol. VIII 162 [outras ocorrências em Hipp. e Galen, v. Hobart 92]; Demetr.: 722 Fgm. 1, 4 Jac. Cf. Gen 25:21) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:31</a> e alternativamente (como Gen 25:21; En 7:2) <span class=\"greek\">ἐν</span> <span class=\"greek\">γαστρὶ</span> <span class=\"greek\">λαμβάνειν</span> GJs 4:2, 4. Passivo <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀνομίαις</span> <span class=\"greek\">συνελήμφθην</span> 1 Cl 18:5 (Ps 50:7).—Com acusativo da criança que há de nascer (Lucian, Ver. Hist. 1, 22; LXX; Demetr.: 722 Fgm. 1, 3 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:36</a>. Passivo <span class=\"greek\">πρὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">συλλημφθῆναι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">κοιλίᾳ</span> antes de ele ser concebido no ventre 2:21.—Em linguagem figurada (cf. <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 14, 3 <span class=\"greek\">τὰ</span> <span class=\"greek\">συλλαμβανόμενα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>; Ps 7:15; TestBenj 7:2 <span class=\"greek\">συλλαμβάνει</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">διάνοια</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βελιάρ</span>; Philo) <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιθυμία</span> <span class=\"greek\">συλλαβοῦσα</span> <span class=\"greek\">τίκτει</span> <span class=\"greek\">ἁμαρτίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:15</a>.</p>\n<p class=\"entry-text\">④ ajudar participando com alguém de uma atividade (literalmente ‘tomar juntamente’), apoiar, auxiliar, ajudar (Aeschyl. et al.) com dativo daquele a quem se presta auxílio (Eur., Med. 812; Hdt. 6, 125; Pla., Leg. 10, 905c; POxy 935, 3; 8 <span class=\"greek\">συλλαμβάνουσι</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">θεοί</span>; 1064, 7; Jos., Ant. 12, 240) <span class=\"greek\">συλλάβωμεν</span> <span class=\"greek\">ἑαυτοῖς</span> ajudemo-nos mutuamente 2 Cl 17:2. Médio (Soph., Phil 282; Pla., Theag. 129e; Diod S 11, 40, 1; Jos., Ant. 4, 198; 7, 341 <span class=\"greek\">τῷ</span> <span class=\"greek\">παιδί</span>; PGiss 25, 4 <span class=\"greek\">συλλαμβανόμενός</span> <span class=\"greek\">μοι</span>; PTebt 448 <span class=\"greek\">συλλαβοῦ</span> <span class=\"greek\">αὐτῷ</span>; Gen 30:8; v. New Docs 4, 56) acudir em auxílio de <span class=\"greek\">τινί</span> alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:7</a> (<span class=\"greek\">βοηθεῖν</span> variante de leitura); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:3</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλλέγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλλέγω</span> (<span class=\"greek\">λέγω</span> ‘reunir’) futuro <span class=\"greek\">συλλέξω</span>; 1.º aoristo <span class=\"greek\">συνέλεξα</span>. Passivo: particípio do aoristo, genitivo plural <span class=\"greek\">συλλεγέντων</span> 3 Macc 1:21; mais-que-perfeito, 3.ª pessoa do singular <span class=\"greek\">συνελέλεκτο</span> Jdth 4:3 (Hom. et al.; inscrições, papiros, LXX; Jos., Vi. 119, Ant. 5, 240 <span class=\"greek\">τὸν</span> <span class=\"greek\">καρπόν</span>; SibOr 8, 55; Just., A I, 67, 6) reunir arrancando ou colhendo, coletar, recolher, colher <span class=\"greek\">τὶ</span> algo, ervas daninhas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:28–30</a>. Passivo, versículo 40. O lugar para onde se leva o que foi recolhido é indicado por <span class=\"greek\">εἰς</span> versículo 48; o lugar de onde se retira é indicado por <span class=\"greek\">ἐκ</span> versículo 41 (<span class=\"greek\">σκάνδαλον</span> 3). Daí também <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀκανθῶν</span> <span class=\"greek\">συλλ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:44</a> (sobre o plural indefinido v. Rydbeck 40); também <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀκανθῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:16</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύλλημμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύλλημμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> termo médico desde Galeno (<span class=\"greek\">συλλαμβάνω</span>) aquilo que é concebido e está no ventre, feto <span class=\"greek\">σύλλημμα</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> (Maria) está grávida pelo Espírito Santo GJs 19:1.—DELG s.v. <span class=\"greek\">λαμβάνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύλληψις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύλληψις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (em vários sentidos desde V a.C.; inscrições, papiros, LXX, Philo; Just., A I, 25, 6) de gravidez, concepção GJs 19:1 Tdf. (por <span class=\"greek\">σύλλημμα</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλλογίζομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλλογίζομαι</span> futuro, 3.ª pessoa do singular <span class=\"greek\">συλλογιεῖται</span> LXX; 1.º aoristo <span class=\"greek\">συνελογισάμην</span>; futuro passivo, 3.ª pessoa do singular <span class=\"greek\">συλλογισθήσεται</span> Num 23:9 (Hdt. et al.; inscrições, papiros, LXX) ponderar ou discutir diversas possibilidades relativas a uma questão, raciocinar, discutir, debater (Pla., Demosth., Polyb.; Is 43:18; Philo, Leg. All. 2, 99; Jos., Bell. 1, 560; 4, 125) <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἑαυτόν</span> consigo mesmo (Plut., Pomp. 651 [60, 3]) ou, no plural, entre si <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:5</a>.—DELG s.v. <span class=\"greek\">λέγω</span>. M-M. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συλλυπέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συλλυπέω</span> (ativo ‘sentir dor ou tristeza com alguém ou ao mesmo tempo’ Aristot., EN 1171b, 7) em nossa literatura, passivo em sentido ativo, entristecer-se com, sentir compaixão (Hdt. et al.; Diod S 4, 11, 2; Is 51:19); em <span class=\"greek\">συλλυπούμενος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πωρώσει</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:5</a> a preposição certamente não tem outro valor senão intensificar o verbo simples, profundamente entristecido pelo endurecimento do coração deles.—DELG s.v. <span class=\"greek\">λύπη</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμβαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμβαίνω</span> imperfeito <span class=\"greek\">συνέβαινον</span>; futuro <span class=\"greek\">συμβήσομαι</span>; 2.º aoristo <span class=\"greek\">συνέβην</span>; perfeito <span class=\"greek\">συμβέβηκα</span> (Aeschyl., Hdt.+)</p>\n<p class=\"entry-text\">① juntar-se a alguém para ir a algum lugar, ir juntamente com, de Paulo, que embarcou com outros AcPl Ha 5, 17 (cf. 5, 15 <span class=\"greek\">ἀνέβη</span>).</p>\n<p class=\"entry-text\">② ocorrer como acontecimento ou processo, acontecer, suceder (Trag., Hdt. +) <span class=\"greek\">συμβαίνει</span> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span> (Trag., Thu. et al.; TestSim 2:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:32</a> (com referência à morte: última vontade e testamento de Aristot. em Diog. L. 5, 11; 12); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:22</a>; 1 Cl 23:3 (citação escriturística de origem desconhecida); B 19:6; D 3:10. <span class=\"greek\">οὕτως</span> <span class=\"greek\">συμβαίνει</span> <span class=\"greek\">πᾶσι</span> Hm 5, 2, 7. <span class=\"greek\">οὕτως</span> <span class=\"greek\">κἀμοὶ</span> <span class=\"greek\">συνέβη</span> a mesma coisa aconteceu comigo GJs 13:1. <span class=\"greek\">καθὼς</span> <span class=\"greek\">φρονοῦσιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">συμβήσεται</span> <span class=\"greek\">αὐτοῖς</span> conforme suas opiniões, assim será o desfecho para eles ISm 2. Seguido de infinitivo (Hdt. 6, 103 e outras ocorrências; inscrições; POxy 491, 10; Ar. 8, 6; Just., D. 23, 1) Hv 3, 7, 6. <span class=\"greek\">συνέβη</span> seguido de acusativo e infinitivo (Hdt. 7, 166 e outras ocorrências; SIG 535, 5; 685, 36f; 1 Esdr 1:23; Jos., Ant. 9, 185; Mel., HE 4, 26, 9; Ath. 5, 1) <span class=\"greek\">συνέβη</span> <span class=\"greek\">βαστάζεσθαι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">στρατιωτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:35</a> (B-D-F §393, 5; 408; Rob. 392; 1043); <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">συνέβη</span> <span class=\"greek\">τελευτῆσαι</span> (<span class=\"greek\">τελέσαι</span> variante de leitura) <span class=\"greek\">τὴν</span> <span class=\"greek\">τάξιν</span> <span class=\"greek\">αὐτῶν</span> mas aconteceu que finalmente sua posição (a dos anjos) foi extinta Papias (4).—<span class=\"greek\">τὸ</span> <span class=\"greek\">συμβεβηκός</span> <span class=\"greek\">τινι</span> o que aconteceu a alguém (Sus 26 Theod.; TestJob 1:6 e outras ocorrências [plural]; Jos., Vi. 51; Just., D. 78, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>. Singular, sem dativo <span class=\"greek\">τὸ</span> <span class=\"greek\">συμβάν</span> o que havia acontecido (Epict. 3, 24, 13; Appian, Hann. 36 §154; TestSol 1:4 [plural]; Agatharchides: 86 Fgm. 20, 211 Jac. [em Jos., C. Ap. 1, 211]; cf. Jos., Ant. 13, 413 <span class=\"greek\">τὰ</span> <span class=\"greek\">ξυμβάντα</span>) GPt 14:59. Plural <span class=\"greek\">τὰ</span> <span class=\"greek\">συμβεβηκότα</span> as coisas que haviam acontecido (Isocr. 5, 18; 1 Macc 4:26; EpArist; Jos., Bell. 4, 43, Ant. 13, 194) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:14</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμβάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμβάλλω</span> imperfeito <span class=\"greek\">συνέβαλλον</span>; 2.º aoristo <span class=\"greek\">συνέβαλον</span>; perfeito <span class=\"greek\">συμβέβληκα</span>. Médio: 2.º aoristo <span class=\"greek\">συνεβαλόμην</span>; perfeito, 3.ª pessoa do singular <span class=\"greek\">συμβέβληται</span> Wsd 5:8. Passivo: aoristo, 3.ª pessoa do singular <span class=\"greek\">συνεβλήθη</span> Sir 22:1f (Hom. et al.; inscrições, papiros, LXX; TestGad 4:4)</p>\n<p class=\"entry-text\">① dedicar-se à ponderação mútua de uma questão, conversar, conferenciar (com <span class=\"greek\">λόγους</span> acrescentado Eur., Iphig. Aul. 830; sem <span class=\"greek\">λ</span>. Plut., Mor. 222c) <span class=\"greek\">τινί</span> com alguém (Epict. 4, 12, 7; Iambl., Vi. Pyth. 2, 12; PFay 129, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:18</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἀλλήλους</span> 4:15.</p>\n<p class=\"entry-text\">② refletir cuidadosamente sobre, considerar, ponderar (Pla., Crat. 384a <span class=\"greek\">μαντείαν</span>; Philo, In Flacc. 139; Jos., Ant. 2, 72 <span class=\"greek\">συμβαλὼν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λογισμῷ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄναρ</span>) <span class=\"greek\">τὰ</span> <span class=\"greek\">ῥήματα</span> <span class=\"greek\">συμβάλλουσα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:19</a> (cf. nossa expressão coloquial ‘juntar todas as peças’).</p>\n<p class=\"entry-text\">③ chegar a uma conclusão mediante comparação, comparar (Hdt. et al.; papiros; Sir 22:1f; Jos., Ant. 1, 105) <span class=\"greek\">τινά</span> <span class=\"greek\">τινι</span> alguém com algo. <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ξύλῳ</span> 1 Cl 23:4=2 Cl 11:3 (citação de origem desconhecida).</p>\n<p class=\"entry-text\">④ convergir para um ponto, encontrar-se, deparar com (Hom. et al.; papiros) <span class=\"greek\">τινί</span> alguém (numa viagem; cf. Jos., Ant. 1, 219; 2, 184; Just., D. 68, 1; 80, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:14</a>. Cf. MPol 8:1.</p>\n<p class=\"entry-text\">⑤ entrar em conflito com alguém</p>\n<p class=\"entry-text\">ⓐ enfrentar, combater alguém <span class=\"greek\">τινί</span> (Polyb. 1, 9, 7; 3, 111, 1 e outras ocorrências; Mitt-Wilck. I/2, 16, 6; 1 Macc 4:34; 2 Macc 8:23; 14:17) <span class=\"greek\">εἰς</span> <span class=\"greek\">πόλεμον</span> enfrentar alguém em batalha, fazer guerra a alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:31</a> (cf. <span class=\"greek\">εἰς</span> <span class=\"greek\">μάχην</span> Polyb. 3, 56, 6; Jos., Bell. 1, 191, Ant. 12, 342; <span class=\"greek\">πρὸς</span> <span class=\"greek\">μάχην</span> Polyb. 10, 37, 4).</p>\n<p class=\"entry-text\">ⓑ contender, disputar <span class=\"greek\">τινί</span> com alguém (PSI 93, 4 <span class=\"greek\">συνέβαλον</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐπιτρόποις</span>) <span class=\"greek\">συμβάλλειν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">πλειόνων</span> contender com ele a respeito de muitas coisas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:53</a> variante de leitura.</p>\n<p class=\"entry-text\">⑥ prestar auxílio, ajudar, ser de auxílio, médio (Philo, Migr. Abr. 219; Just., D. 46, 7) <span class=\"greek\">τινί</span> (a) alguém (Pla.; Demosth. 21, 133; Antiphon 5, 79 p. 138, 37 <span class=\"greek\">πολλὰ</span> <span class=\"greek\">συμβ</span>. <span class=\"greek\">τοῖς</span> <span class=\"greek\">βουλομένοις</span>; Polyb. 2, 13, 1; Epict. 3, 22, 78 <span class=\"greek\">πλείονά</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ς</span>.; PLond VI, 1915, 13; Wsd 5:8; Jos., Ant. 12, 312; Ar. [Milne 74, 22]; Tat. 24, 1) Apolo <span class=\"greek\">συνεβάλετο</span> <span class=\"greek\">πολὺ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πεπιστευκόσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:27</a>. <span class=\"greek\">συνεβάλλοντο</span> … <span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀδελφοὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">λυπηθῆναι</span> <span class=\"greek\">Παῦλον</span> toda a comunidade de irmãos estava ajudando (tanto quanto possível) … para que Paulo não se entristecesse AcPl Ha 7, 17.—M-M s.v. <span class=\"greek\">συνβάλλω</span>. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμβασιλεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμβασιλεύω</span> futuro <span class=\"greek\">συμβασιλεύσω</span> (Polyb. 30, 2, 4; Dionys. Hal., Strabo; Lucian, Dial. Deor. 16, 2; Plut., Lyc. 42 [5, 5], Num. 61 [3, 6], Anton. 941 [54, 4]; 1 Esdr 8:26 variante de leitura) reinar conjuntamente, governar (como rei) com alguém, em linguagem figurada da situação escatológica em que os cristãos hão de compartilhar a realeza com seu Senhor régio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:12</a>; Pol 5:2. Paulo declara ironicamente que os coríntios alcançaram a realeza; deseja que a tivessem alcançado, pois então estaria reinando com eles; na realidade, ainda suportava uma vida miserável (cf. versículo 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:8</a>.—DELG s.v. <span class=\"greek\">βασιλεύς</span>. M-M s.v. <span class=\"greek\">συνβασιλεύω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμβιβάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμβιβάζω</span> futuro <span class=\"greek\">συμβιβάσω</span>, ático <span class=\"greek\">συμβιβῶ</span> Ps 31:8; 1.º aoristo <span class=\"greek\">συνεβίβασα</span>, particípio passivo <span class=\"greek\">συμβιβασθείς</span> (<span class=\"greek\">βιβάζω</span> ‘fazer ir’; Hdt. et al.; inscrições, LXX).</p>\n<p class=\"entry-text\">① reunir numa unidade, unir</p>\n<p class=\"entry-text\">ⓐ literalmente, do corpo, que é mantido unido por tendões, ligamentos, articulações <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">συμβιβαζόμενον</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἁφῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:16</a> (GWhitaker, JTS 31, 1930, 48f); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:19</a>.</p>\n<p class=\"entry-text\">ⓑ figuradamente, unir, entrelaçar (Hdt. 1, 74; Thu. 2, 29, 6; Pla., Prot. 337e) passivo <span class=\"greek\">συμβιβασθέντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a> (assim Lghtf. et al., NRSV. Mas v. 4 abaixo).</p>\n<p class=\"entry-text\">② chegar a uma conclusão diante de evidências, concluir, inferir (Pla., Hipp. Min. 369d, Rep. 6, 504a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:10</a> (seguido de <span class=\"greek\">ὅτι</span>).</p>\n<p class=\"entry-text\">③ apresentar uma conclusão lógica, demonstrar, provar (Aristot., Top. 7, 5, 150a, 36 [<span class=\"greek\">ὅτι</span>]; 8, 3, 154b, 27; 8, 11, 157b, 37; Iambl., Vi. Pyth. 13, 60) <span class=\"greek\">συμβιβάζων</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:22</a>.</p>\n<p class=\"entry-text\">④ aconselhar dando instruções, instruir, ensinar, aconselhar <span class=\"greek\">τινά</span> alguém (LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:16</a> (Is 40:13f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:33</a> (variantes de leitura <span class=\"greek\">προεβίβασαν</span>, <span class=\"greek\">κατεβίβασαν</span>; divergentemente PLampe, BZ 36, ’92, 72–74).—Alguns (p. ex. MDibelius, Mft.) classificam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:2</a> aqui (v. 1b acima).—DELG s.v. <span class=\"greek\">βαίνω</span>. M-M. s.v. <span class=\"greek\">συνβιβάζω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σύμβιος, ον</h1><div class=\"entry-meta\"><span>adjetivo substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σύμβιος</span>, <span class=\"greek\">ον</span> ‘que vive juntamente’ (Aristot. et al.; TestJud 23:3; TestIss 7:2 variante de leitura [por <span class=\"greek\">γυναικός</span>]; Philo, Poster. Cai. 78) substantivado ‘companheiro’, depois especialmente <span class=\"greek\">ὁ</span>, <span class=\"greek\">ἡ</span> <span class=\"greek\">ς</span>. marido, esposa (inscrições e frequentemente em papiros; New Docs 1 n.º 18, 18) IPol 5:1 MMacDonald, NTS 40, ’94, 105–25; Hv 2, 2, 3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμβουλεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμβουλεύω</span> futuro <span class=\"greek\">συμβουλεύσω</span> LXX; 1.º aoristo <span class=\"greek\">συνεβούλευσα</span> (v. os quatro verbetes seguintes; Theognis, Trag., Hdt.+)</p>\n<p class=\"entry-text\">① dar conselho sobre um curso de ação, aconselhar, ativo <span class=\"greek\">τινί</span> alguém (Ex 18:19; Jos., C. Ap. 1, 309a; Just., D. 56, 8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:14</a>. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> aconselhar alguém (a fazer) algo (Hdt. 7, 237 e outras ocorrências; 3 Km 1:12 <span class=\"greek\">συμβουλεύσω</span> <span class=\"greek\">σοι</span> <span class=\"greek\">συμβουλίαν</span>) MPol 8:2. Com dativo seguido de infinitivo (Hdt. et al.; BGU 1097, 8 [I d.C.]; 4 Macc 8:29; Jos., Ant. 12, 384; Tat. 27, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:18</a>. Uso absoluto (Diog. L. 1, 92a; Jos., Bell. 2, 345) 2 Cl 15:1.</p>\n<p class=\"entry-text\">② envolver-se com outros na elaboração de um plano de ação, deliberar, tramar, médio (Jos., Ant. 8, 379; TestJud 13:4) seguido de <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:53</a> variante de leitura. Seguido de infinitivo de finalidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:23</a>.</p>\n<p class=\"entry-text\">③ refletir cuidadosamente sobre algo, meditar sobre, considerar, médio (PPetr II, 13, 6, 12; PSI 236, 30) <span class=\"greek\">τὶ</span> algo Hv 1, 2, 2.—DELG s.v. <span class=\"greek\">βούλομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμβουλή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμβουλή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> conselho, aconselhamento (v. o verbete anterior e os três seguintes; Hdt. 1, 157 e outras ocorrências; TestSol; GrBar 3:5 <span class=\"greek\">ς</span>. <span class=\"greek\">δοῦναι</span>; Philo, Fuga 24; Jos., Ant. 19, 192) <span class=\"greek\">δέχεσθαι</span> <span class=\"greek\">ς</span>. aceitar conselho 1 Cl 58:2.—DELG s.v. <span class=\"greek\">βούλομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0337-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">συμβουλία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">συμβουλία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> conselho, aconselhamento (v. os dois verbetes anteriores e os dois seguintes; Hdt. et al.; inscrições, papiros, LXX, Philo; Jos., Ant. 5, 336; 8, 277 e outras ocorrências) <span class=\"greek\">συμβουλίαν</span> <span class=\"greek\">ποιεῖσθαι</span> <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> dar conselho sobre algo (Diod S 12, 17, 2) 2 Cl 15:1. <span class=\"greek\">γνώμης</span> <span class=\"greek\">ἀγαθῆς</span> <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">συμβουλίαν</span> aceitar conselho bem-intencionado B 21:2 (cf. Vi. Aesopi I, 26 Eb. <span class=\"greek\">συμβ</span>. <span class=\"greek\">λαμβάνειν</span>).—DELG s.v. <span class=\"greek\">βούλομαι</span>.</p></section></article>"};
